// ---- core/render.js
// Contract messages -> WhatsApp Cloud API payloads, enforcing Meta's field
// limits. Meta rejects the WHOLE message if any field is too long, so we
// truncate here rather than lose the reply.
const LIMITS = {
  text: 4096,
  body: 1024,         // interactive body
  buttonTitle: 20,
  maxButtons: 3,
  listButton: 20,
  sectionTitle: 24,
  rowTitle: 24,
  rowDescription: 72,
  maxRows: 10,
  id: 256,
};

function cut(s, n) {
  const str = String(s ?? '');
  const chars = Array.from(str); // count code points, not UTF-16 units (Hindi/emoji)
  return chars.length <= n ? str : chars.slice(0, n - 1).join('') + '…';
}

// Split long text at paragraph/line boundaries so each part fits.
function splitText(text, max = LIMITS.text) {
  const parts = [];
  let rest = String(text ?? '');
  while (Array.from(rest).length > max) {
    const chars = Array.from(rest);
    const window = chars.slice(0, max).join('');
    let at = window.lastIndexOf('\n\n');
    if (at < max / 2) at = window.lastIndexOf('\n');
    if (at < max / 2) at = window.lastIndexOf(' ');
    if (at <= 0) at = window.length;
    parts.push(window.slice(0, at).trimEnd());
    rest = rest.slice(at).trimStart();
  }
  if (rest.length || parts.length === 0) parts.push(rest);
  return parts;
}

function renderMessage(msg, to) {
  const base = { messaging_product: 'whatsapp', recipient_type: 'individual', to };
  switch (msg.type) {
    case 'text':
      return splitText(msg.body).map((body) => ({ ...base, type: 'text', text: { body, preview_url: true } }));
    case 'buttons':
      return [{
        ...base,
        type: 'interactive',
        interactive: {
          type: 'button',
          body: { text: cut(msg.body, LIMITS.body) },
          action: {
            buttons: (msg.buttons || []).slice(0, LIMITS.maxButtons).map((b) => ({
              type: 'reply',
              reply: { id: cut(b.id, LIMITS.id), title: cut(b.title, LIMITS.buttonTitle) },
            })),
          },
        },
      }];
    case 'list': {
      let remaining = LIMITS.maxRows;
      const sections = [];
      for (const s of msg.sections || []) {
        if (remaining <= 0) break;
        const rows = (s.rows || []).slice(0, remaining).map((r) => {
          const row = { id: cut(r.id, LIMITS.id), title: cut(r.title, LIMITS.rowTitle) };
          if (r.description) row.description = cut(r.description, LIMITS.rowDescription);
          return row;
        });
        remaining -= rows.length;
        if (rows.length) sections.push({ title: cut(s.title || '', LIMITS.sectionTitle), rows });
      }
      return [{
        ...base,
        type: 'interactive',
        interactive: {
          type: 'list',
          body: { text: cut(msg.body, LIMITS.body) },
          action: { button: cut(msg.button || 'Menu', LIMITS.listButton), sections },
        },
      }];
    }
    case 'location':
      return [{
        ...base,
        type: 'location',
        location: { latitude: msg.lat, longitude: msg.lon, name: msg.name || '', address: msg.address || '' },
      }];
    case 'location_request':
      return [{
        ...base,
        type: 'interactive',
        interactive: { type: 'location_request_message', body: { text: cut(msg.body, LIMITS.body) }, action: { name: 'send_location' } },
      }];
    case 'template':
      return [{ ...base, type: 'template', template: msg.template }];
    default:
      throw new Error(`unknown message type: ${msg.type}`);
  }
}

// All user-visible strings in a payload (for the phone guard and logging).
function visibleText(payload) {
  const out = [];
  if (payload.text) out.push(payload.text.body);
  const i = payload.interactive;
  if (i) {
    out.push(i.body && i.body.text);
    for (const b of (i.action && i.action.buttons) || []) out.push(b.reply.title);
    for (const s of (i.action && i.action.sections) || []) {
      out.push(s.title);
      for (const r of s.rows) out.push(r.title, r.description);
    }
  }
  if (payload.location) out.push(payload.location.name, payload.location.address);
  return out.filter(Boolean).join('\n');
}

// ---- core/phone_guard.js
// Find phone-number-like tokens in outgoing text. Every one of them must exist
// in core.number_registry (checked in SQL by core.disallowed_numbers), so the
// bot can never send a number that isn't in the verified data.
const CANDIDATE = /\+?\d[\d \t.-]{4,}\d/g; // spaces/dots/hyphens inside one line only - never across a line break
const COORD = /(?<![\d.])\d{1,3}\.\d{4,}(?![\d.])/g; // lat/lon in map links, e.g. 25.678912,85.123456
// Tokens that look numeric but are never phone numbers
const NOT_PHONE = [
  /^\d{4}-\d{2}-\d{2}$/,                  // 2026-11-24
  /^\d{1,2}[.-]\d{1,2}[.-]\d{2,4}$/,      // 24-11-2026, 24.11.26
  /^\d{4}-\d{2}$/,                        // 2025-26
  /^\d{1,2}\.\d{2}\s*-\s*\d{1,2}\.\d{2}$/, // 18.00-20.00
];
// Zero of each Unicode decimal-digit block an LLM or a sheet might use:
// Arabic-Indic, Extended Arabic-Indic, Devanagari, Bengali, Gurmukhi, Gujarati,
// Oriya, Tamil, Telugu, Kannada, Malayalam, full-width.
const DIGIT_ZEROS = [0x660, 0x6f0, 0x966, 0x9e6, 0xa66, 0xae6, 0xb66, 0xbe6, 0xc66, 0xce6, 0xd66, 0xff10];

// "९८७६५४३२१०" -> "9876543210", so a number can't slip past in another script.
function asciiDigits(text) {
  return String(text || '').replace(/\p{Nd}/gu, (ch) => {
    const cp = ch.codePointAt(0);
    const zero = DIGIT_ZEROS.find((z) => cp >= z && cp <= z + 9);
    return zero === undefined ? ch : String(cp - zero);
  });
}

function extractPhones(text) {
  const found = new Set();
  const scanned = asciiDigits(text).replace(COORD, ' ');
  for (const m of scanned.matchAll(CANDIDATE)) {
    const token = m[0].trim().replace(/[.-]+$/, '');
    if (NOT_PHONE.some((re) => re.test(token))) continue;
    const digits = token.replace(/\D/g, '');
    if (digits.length < 6 || digits.length > 13) continue;
    found.add(digits);
  }
  return Array.from(found);
}

// ---- core/deliver.js
// Render -> phone guard -> WhatsApp Cloud API, strictly one message after
// another (awaiting each response) so a citizen's messages arrive in order.
// Returns one log entry per payload for core.rpc_finish_turn().
// Depends on: renderMessage/visibleText (render.js), extractPhones (phone_guard.js).
// `allowed` = normalised numbers from core.number_registry; `http` = this.helpers.httpRequest.
function normDigits(p) {
  const d = String(p || '').replace(/\D/g, '');
  return /^91[6-9]\d{9}$/.test(d) ? d.slice(2) : d;
}

async function deliverMessages(send, allowed, cfg, http) {
  const ok = new Set((allowed || []).map(normDigits));
  const url = `${cfg.base || 'https://graph.facebook.com'}/${cfg.version || 'v23.0'}/${cfg.phoneId}/messages`;
  const logs = [];
  for (const m of (send && send.messages) || []) {
    for (let payload of renderMessage(m, send.to)) {
      let text = visibleText(payload);
      let blocked = null;
      const bad = extractPhones(text).filter((p) => !ok.has(normDigits(p)));
      if (bad.length) {
        // A number that is not in the verified data must never reach a citizen.
        blocked = bad;
        text = send.lang === 'en' ? 'Sorry, this information is not available right now.' : 'माफ़ कीजिए, यह जानकारी अभी उपलब्ध नहीं है।';
        payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: send.to, type: 'text', text: { body: text } };
      }
      let result = null;
      for (let attempt = 1; attempt <= 2 && !result; attempt++) {
        try {
          const res = await http({ method: 'POST', url, json: true, body: payload, timeout: 10000,
            headers: { Authorization: `Bearer ${cfg.token}` }, returnFullResponse: true, ignoreHttpStatusErrors: true });
          const retryable = res.statusCode === 429 || res.statusCode >= 500;
          if (res.statusCode < 300) result = { out_id: ((res.body.messages || [])[0] || {}).id || null, error: null };
          else if (!retryable || attempt === 2) result = { out_id: null, error: `HTTP ${res.statusCode}: ${JSON.stringify(res.body).slice(0, 400)}` };
        } catch (e) {
          if (attempt === 2) result = { out_id: null, error: String(e.message || e).slice(0, 400) };
        }
        if (!result) await new Promise((r) => setTimeout(r, 1000));
      }
      logs.push({ wa_hash: send.wa_hash, service_key: send.service_key, kind: m.type, text,
        out_id: result.out_id, error: result.error || (blocked ? `phone_guard:${blocked.join(',')}` : null) });
    }
  }
  return logs;
}

// ---- services/complaint_notify.js
// Builds the citizen-facing WhatsApp message for a complaint status change.
// Used by the notification bridge (core-11-notify-poll). Pure: given one
// grievance.notification_outbox row's payload and the citizen's language,
// returns a 'messages' array for deliverMessages() (core/deliver.js).
// Depends on: extractPhones (core/phone_guard.js), loaded in the same Code node.
//
// Always an approved WhatsApp *template*, never free text: a status change can
// come days after the citizen last wrote, outside WhatsApp's 24-hour customer
// service window, where the Cloud API still answers 200 for free text but
// Meta drops it later (error 131047) - the citizen would silently never hear.
// The template must exist in Meta's WhatsApp Manager in both languages
// (docs/runbook.md, "Complaint status template"), with three body variables:
//   {{1}} complaint id   {{2}} status   {{3}} note
const STATUS_LABEL = {
  open: { en: 'Open', hi: 'खुला' },
  assigned: { en: 'Assigned to an officer', hi: 'अधिकारी को सौंपी गई' },
  in_progress: { en: 'In progress', hi: 'प्रक्रिया में' },
  resolved: { en: 'Resolved', hi: 'हल हो गई' },
  closed: { en: 'Resolved and closed', hi: 'हल होकर बंद' },
};

const DEFAULT_NOTE = {
  assigned: { en: 'An officer will look into it.', hi: 'एक अधिकारी इसे देखेंगे।' },
  in_progress: { en: 'Work on it has started.', hi: 'इस पर काम शुरू हो गया है।' },
  resolved: { en: 'The issue has been resolved.', hi: 'समस्या का समाधान कर दिया गया है।' },
  closed: { en: 'The issue has been resolved.', hi: 'समस्या का समाधान कर दिया गया है।' },
};

const NOTE_MAX = 300;

function notifyLang(lang) {
  return lang === 'en' ? 'en' : 'hi';
}

function statusLabel(status, lang) {
  return (STATUS_LABEL[status] || {})[notifyLang(lang)] || status;
}

// Meta rejects template variables that are empty or contain newlines, tabs or
// more than four spaces in a row.
function templateParam(s) {
  return String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
}

// The closing officer's own words, if they are safe to show: template text is
// not checked by deliver.js's phone guard (it only reads text/interactive
// bodies), so any phone-number-like run here drops the remark entirely rather
// than let an unverified number reach a citizen.
function citizenNote(payload, lang) {
  const l = notifyLang(lang);
  const fallback = ((DEFAULT_NOTE[payload.status] || {})[l]) || '-';
  const remark = templateParam(payload.remark);
  if (!remark) return fallback;
  if (typeof extractPhones !== 'function' || extractPhones(remark).length) return fallback;
  const chars = Array.from(remark);
  return chars.length > NOTE_MAX ? `${chars.slice(0, NOTE_MAX - 1).join('')}…` : remark;
}

// payload: { complaint_id, status, remark? } (grievance.notification_outbox.payload)
// opts.template: the approved template's name (COMPLAINT_UPDATE_TEMPLATE).
function buildStatusNotification(payload, lang, opts = {}) {
  const p = payload || {};
  if (!p.complaint_id || !STATUS_LABEL[p.status]) throw new Error(`bad notification payload: ${JSON.stringify(p).slice(0, 200)}`);
  const l = notifyLang(lang);
  return [{
    type: 'template',
    template: {
      name: opts.template || 'complaint_update',
      language: { code: l },
      components: [{ type: 'body', parameters: [
        { type: 'text', text: templateParam(p.complaint_id) },
        { type: 'text', text: statusLabel(p.status, l) },
        { type: 'text', text: citizenNote(p, l) },
      ] }],
    },
  }];
}

// ---- main

const { batch, allowed } = $input.first().json;
const rows = batch || [];
const cfg = { base: $env.WA_API_BASE, version: $env.GRAPH_API_VERSION, phoneId: $env.WHATSAPP_PHONE_NUMBER_ID, token: $env.WHATSAPP_ACCESS_TOKEN };
const http = this.helpers.httpRequest.bind(this.helpers);
const template = $env.COMPLAINT_UPDATE_TEMPLATE || 'complaint_update';
const outs = [];
const results = [];
// one citizen after another, like every other send in this bot
for (const row of rows) {
  if (!row.to) {
    results.push({ id: row.id, ok: false, final: true, error: 'no WhatsApp number on record for this citizen (purged?)' });
    continue;
  }
  let messages;
  try {
    messages = buildStatusNotification(row.payload, row.lang, { template });
  } catch (e) {
    results.push({ id: row.id, ok: false, final: true, error: String(e.message || e) });
    continue;
  }
  const logs = await deliverMessages({ to: row.to, wa_hash: row.wa_hash, lang: row.lang, service_key: 'complaint', messages }, allowed, cfg, http);
  for (const l of logs) outs.push({ ...l, text: l.text || ('[' + template + '] ' + row.complaint_id + ' ' + row.payload.status) });
  const err = logs.map((l) => l.error).find(Boolean);
  results.push({ id: row.id, ok: logs.length > 0 && !err, error: err || (logs.length ? null : 'nothing sent'), out_id: (logs[0] || {}).out_id || null });
}
return [{ json: { claimed: rows.length, finish: { end: null, outs }, results } }];

